-- create "data_export_requests" table
CREATE TABLE "data_export_requests" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "idempotency_key" character varying NULL, "status" character varying NOT NULL DEFAULT 'requested', "object_key" character varying NULL, "size_bytes" bigint NOT NULL DEFAULT 0, "failure_reason" character varying NOT NULL DEFAULT '', "claimed_at" timestamptz NULL, "completed_at" timestamptz NULL, "expires_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "dataexportrequest_account_id_idempotency_key" to table: "data_export_requests"
CREATE UNIQUE INDEX "dataexportrequest_account_id_idempotency_key" ON "data_export_requests" ("account_id", "idempotency_key");
-- create index "dataexportrequest_status_created_at" to table: "data_export_requests"
CREATE INDEX "dataexportrequest_status_created_at" ON "data_export_requests" ("status", "created_at");
-- create "deletion_requests" table
CREATE TABLE "deletion_requests" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "status" character varying NOT NULL DEFAULT 'pending', "reason" character varying NOT NULL DEFAULT '', "scheduled_for" timestamptz NOT NULL, "retention_snapshot" jsonb NOT NULL, "cancelled_at" timestamptz NULL, "executed_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "deletionrequest_account_id_status" to table: "deletion_requests"
CREATE INDEX "deletionrequest_account_id_status" ON "deletion_requests" ("account_id", "status");
-- create index "deletionrequest_status_scheduled_for" to table: "deletion_requests"
CREATE INDEX "deletionrequest_status_scheduled_for" ON "deletion_requests" ("status", "scheduled_for");
-- create "geo_admin_areas" table
CREATE TABLE "geo_admin_areas" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "region_id" uuid NOT NULL, "name" character varying NOT NULL, PRIMARY KEY ("id"));
-- create index "geoadminarea_region_id_name" to table: "geo_admin_areas"
CREATE UNIQUE INDEX "geoadminarea_region_id_name" ON "geo_admin_areas" ("region_id", "name");
-- create "geo_cities" table
CREATE TABLE "geo_cities" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "region_id" uuid NOT NULL, "admin_area_id" uuid NULL, "name" character varying NOT NULL, PRIMARY KEY ("id"));
-- create index "geocity_admin_area_id" to table: "geo_cities"
CREATE INDEX "geocity_admin_area_id" ON "geo_cities" ("admin_area_id");
-- create index "geocity_region_id_name" to table: "geo_cities"
CREATE UNIQUE INDEX "geocity_region_id_name" ON "geo_cities" ("region_id", "name");
-- create "geo_countries" table
CREATE TABLE "geo_countries" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "code" character varying NOT NULL, "name" character varying NOT NULL, "region_label" character varying NULL, "admin_area_label" character varying NULL, "postal_code_required" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"));
-- create index "geocountry_code" to table: "geo_countries"
CREATE UNIQUE INDEX "geocountry_code" ON "geo_countries" ("code");
-- create "geo_regions" table
CREATE TABLE "geo_regions" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "country_id" uuid NOT NULL, "country_code" character varying NOT NULL, "code" character varying NULL, "name" character varying NOT NULL, PRIMARY KEY ("id"));
-- create index "georegion_country_code_name" to table: "geo_regions"
CREATE UNIQUE INDEX "georegion_country_code_name" ON "geo_regions" ("country_code", "name");
-- create index "georegion_country_id" to table: "geo_regions"
CREATE INDEX "georegion_country_id" ON "geo_regions" ("country_id");
-- create "policy_versions" table
CREATE TABLE "policy_versions" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "kind" character varying NOT NULL, "version" character varying NOT NULL, "effective_at" timestamptz NOT NULL, "summary" character varying NOT NULL DEFAULT '', "content_url" character varying NOT NULL DEFAULT '', "published_by" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- create index "policyversion_kind_effective_at" to table: "policy_versions"
CREATE INDEX "policyversion_kind_effective_at" ON "policy_versions" ("kind", "effective_at");
-- create index "policyversion_kind_version" to table: "policy_versions"
CREATE UNIQUE INDEX "policyversion_kind_version" ON "policy_versions" ("kind", "version");
-- create "privacy_settings" table
CREATE TABLE "privacy_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "account_id" uuid NOT NULL, "analytics" boolean NOT NULL DEFAULT false, "personalization" boolean NOT NULL DEFAULT false, "personalized_ads" boolean NOT NULL DEFAULT false, "marketing" boolean NOT NULL DEFAULT false, "policy_version" character varying NOT NULL DEFAULT '', "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "privacysetting_account_id" to table: "privacy_settings"
CREATE UNIQUE INDEX "privacysetting_account_id" ON "privacy_settings" ("account_id");
-- create "retention_policies" table
CREATE TABLE "retention_policies" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "category" character varying NOT NULL, "action" character varying NOT NULL DEFAULT 'retain', "retention_days" bigint NULL, "needs_legal_review" boolean NOT NULL DEFAULT true, "version" bigint NOT NULL DEFAULT 1, "updated_by" character varying NOT NULL DEFAULT 'system', "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "retentionpolicy_category" to table: "retention_policies"
CREATE UNIQUE INDEX "retentionpolicy_category" ON "retention_policies" ("category");
-- create "shipping_addresses" table
CREATE TABLE "shipping_addresses" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "label" character varying NOT NULL DEFAULT '', "recipient_name" character varying NOT NULL, "phone" character varying NOT NULL, "line1" character varying NOT NULL, "line2" character varying NOT NULL DEFAULT '', "postal_code" character varying NOT NULL DEFAULT '', "details" character varying NOT NULL DEFAULT '', "country_code" character varying NOT NULL, "region_id" uuid NULL, "admin_area_id" uuid NULL, "city_id" uuid NULL, "free_text_city" character varying NOT NULL DEFAULT '', "free_text_state" character varying NOT NULL DEFAULT '', "is_default" boolean NOT NULL DEFAULT false, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "shippingaddress_account_id_created_at" to table: "shipping_addresses"
CREATE INDEX "shippingaddress_account_id_created_at" ON "shipping_addresses" ("account_id", "created_at");
-- create "terms_acceptances" table
CREATE TABLE "terms_acceptances" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "terms_version" character varying NOT NULL, "accepted_at" timestamptz NOT NULL, "ip_address" character varying NOT NULL DEFAULT '', "user_agent" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- create index "termsacceptance_account_id_terms_version" to table: "terms_acceptances"
CREATE UNIQUE INDEX "termsacceptance_account_id_terms_version" ON "terms_acceptances" ("account_id", "terms_version");
-- create "user_consents" table
CREATE TABLE "user_consents" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NULL, "device_id" character varying NULL, "consent_type" character varying NOT NULL, "status" character varying NOT NULL, "policy_version" character varying NOT NULL, "consented_at" timestamptz NOT NULL, "withdrawn_at" timestamptz NULL, "ip_address" character varying NOT NULL DEFAULT '', "user_agent" character varying NOT NULL DEFAULT '', "source" character varying NOT NULL DEFAULT 'direct', PRIMARY KEY ("id"));
-- create index "userconsent_account_id_consent_type_created_at" to table: "user_consents"
CREATE INDEX "userconsent_account_id_consent_type_created_at" ON "user_consents" ("account_id", "consent_type", "created_at");
-- create index "userconsent_device_id_consent_type_created_at" to table: "user_consents"
CREATE INDEX "userconsent_device_id_consent_type_created_at" ON "user_consents" ("device_id", "consent_type", "created_at");
